import { z } from "zod";

export enum Plan {
  Free = "free",
  Pro = "pro",
  Team = "team",
}

/** A new account, as posted by the signup form. */
export const Signup = z.object({
  id: z.string().uuid(),
  email: z.string().email(),
  name: z.string().min(1).max(80),
  age: z.number().int().min(13).optional(),
  website: z.string().url().optional(),
  ip: z.string().ip(),
  plan: z.nativeEnum(Plan),
  /** feature flags, e.g. { beta: true } */
  flags: z.record(z.boolean()),
  prefs: z
    .object({
      theme: z.enum(["light", "dark"]).default("light"),
      /** comes in as a string from the form; stored as a number */
      retries: z.string().transform(Number).default("3"),
    })
    .default({}),
});
export type Signup = z.infer<typeof Signup>;

/** Service config, usually read from environment variables (so: strings). */
export const Config = z.object({
  port: z.string().transform(Number).default("8080"),
  hosts: z.array(z.string().ip()).min(1),
  timeoutMs: z.number().positive().default(5000),
});
export type Config = z.infer<typeof Config>;

/** A webhook handler: (event, payloadBytes) => void, checked at the boundary. */
export const Hook = z.function().args(z.string(), z.number()).returns(z.void());

import { z } from "zod";
import { Config, Signup } from "./schemas";

export type Result<T> = { ok: true; value: T } | { ok: false; problems: string[] };

/** Turn a ZodError into "path: message" lines a human can read. */
export function describe(err: z.ZodError): string[] {
  return err.errors.map((e) => `${e.path.join(".") || "(root)"}: ${e.message}`);
}

export function parseSignup(input: unknown): Result<Signup> {
  const r = Signup.safeParse(input);
  return r.success ? { ok: true, value: r.data } : { ok: false, problems: describe(r.error) };
}

export function parseConfig(env: Record<string, unknown>): Result<Config> {
  const r = Config.safeParse(env);
  return r.success ? { ok: true, value: r.data } : { ok: false, problems: describe(r.error) };
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { Hook, parseConfig, parseSignup } from "../src";

const good = {
  id: "9b2c4e6a-1f3d-4b8e-9c7a-2d5e8f1a3b6c",
  email: "ada@example.com",
  name: "Ada",
  ip: "10.0.0.7",
  plan: "pro",
  flags: { beta: true },
};

test("accepts a valid signup and fills the preference defaults", () => {
  const r = parseSignup(good);
  assert.equal(r.ok, true);
  if (r.ok) {
    assert.equal(r.value.prefs.theme, "light");
    assert.equal(r.value.prefs.retries, 3);
  }
});

test("rejects a bad email with a readable, path-prefixed problem", () => {
  const r = parseSignup({ ...good, email: "not-an-email" });
  assert.equal(r.ok, false);
  if (!r.ok) assert.match(r.problems[0], /^email: /);
});

test("rejects a non-boolean feature flag", () => {
  const r = parseSignup({ ...good, flags: { beta: "yes" } });
  assert.equal(r.ok, false);
});

test("config: port comes in as a string and defaults to 8080", () => {
  const r = parseConfig({ hosts: ["127.0.0.1"] });
  assert.equal(r.ok, true);
  if (r.ok) {
    assert.equal(r.value.port, 8080);
    assert.equal(r.value.timeoutMs, 5000);
  }
  const r2 = parseConfig({ port: "3000", hosts: ["10.0.0.1"] });
  assert.equal(r2.ok, true);
  if (r2.ok) assert.equal(r2.value.port, 3000);
});

test("hook: the implementation is checked at the boundary", () => {
  const calls: string[] = [];
  const handler = Hook.implement((event, bytes) => {
    calls.push(`${event}:${bytes}`);
  });
  handler("signup", 42);
  assert.deepEqual(calls, ["signup:42"]);
});

// Replay the golden corpus through the CURRENT build. Which requests get a different answer?
// Run:  npm run build && node corpus/replay.js [--json]
const fs = require("fs");
const path = require("path");
const { parseSignup } = require("../dist/src");
const { answer, key } = require("./canon");

const file = fs.readdirSync(__dirname).filter((f) => /^signups-.*\.jsonl$/.test(f)).sort().pop();
const rows = fs.readFileSync(path.join(__dirname, file), "utf8").trim().split("\n").map((l) => JSON.parse(l));

const short = (v, n = 52) => { const s = JSON.stringify(v); return s.length > n ? s.slice(0, n - 1) + "…" : s; };

// Where does a value differ? The first differing path, e.g. "prefs.theme".
function where(a, b, p = "") {
  if (JSON.stringify(a) === JSON.stringify(b)) return null;
  if (a && b && typeof a === "object" && typeof b === "object") {
    for (const k of new Set([...Object.keys(a), ...Object.keys(b)])) {
      const w = where(a[k], b[k], p ? `${p}.${k}` : k);
      if (w) return w;
    }
  }
  return p || "(root)";
}

const diffs = [];
for (const r of rows) {
  const now = answer(parseSignup(r.input));
  if (key(now) === key(r.answer)) continue;
  const was = r.answer;
  let field, change;
  if (was.ok && !now.ok) { field = now.fields.join(","); change = "was ACCEPTED, now REJECTED"; }
  else if (!was.ok && now.ok) { field = was.fields.join(","); change = "was REJECTED, now ACCEPTED"; }
  else if (was.ok && now.ok) { field = where(was.value, now.value); change = "accepted, but the PARSED VALUE changed"; }
  else { field = [...new Set([...was.fields, ...now.fields])].join(","); change = "rejected, but for a different field"; }
  const top = change.startsWith("rejected, but") ? field : field.split(/[.,]/)[0];
  const detail = was.ok && now.ok
    ? `${field}: was ${short(field.split(".").reduce((o, k) => o?.[k], was.value))} now ${short(field.split(".").reduce((o, k) => o?.[k], now.value))}`
    : now.ok ? `${field}: zod 3 said "${(was.problems || [])[0] || "?"}"` : `${now.problems[0]}`;
  diffs.push({ n: r.n, group: `${top} — ${change}`, input: r.input[top.split(",")[0]], detail });
}

if (process.argv.includes("--json")) { console.log(JSON.stringify({ file, total: rows.length, diffs }, null, 1)); process.exit(0); }

console.log(`CORPUS ${file}: ${rows.length} recorded requests (answers from production, zod 3)`);
console.log(`  same answer : ${rows.length - diffs.length}`);
console.log(`  DIFFERENT   : ${diffs.length}`);
const groups = {};
for (const d of diffs) (groups[d.group] ||= []).push(d);
for (const [g, ds] of Object.entries(groups)) {
  console.log(`\n[${ds.length}] ${g}`);
  for (const d of ds.slice(0, 4)) console.log(`   #${String(d.n).padEnd(4)} ${short(d.input, 60).padEnd(62)} ${d.detail}`);
  if (ds.length > 4) console.log(`   … and ${ds.length - 4} more`);
}
if (!diffs.length) console.log("\nCORPUS OK: yesterday's inputs get yesterday's answers.");
process.exit(diffs.length ? 1 : 0);

// What counts as "the same answer": the verdict, the parsed value, and WHICH fields failed.
// Not the error text: zod 4 rewrote every message, and wording isn't behaviour.
function canon(v) {
  if (Array.isArray(v)) return v.map(canon);
  if (v && typeof v === "object") {
    const o = {};
    for (const k of Object.keys(v).sort()) o[k] = canon(v[k]);
    return o;
  }
  return v;
}

/** parseSignup's Result -> the comparable answer. */
function answer(r) {
  if (r.ok) return { ok: true, value: canon(r.value) };
  const fields = [...new Set(r.problems.map((p) => p.split(":")[0]))].sort();
  return { ok: false, fields, problems: r.problems };
}

const key = (a) => JSON.stringify(a.ok ? { ok: true, value: a.value } : { ok: false, fields: a.fields });

module.exports = { canon, answer, key };

